 * Core type contracts for the validation and sanitization pipeline.
 *
 * Principles:
 * - All validation returns Result<T, ValidationError[]>, never throws.
 * - Sanitized output types are distinct from raw input types (nominal typing via brands).
 * - Parameterized queries are structurally incapable of containing injection.
 */

// ---------------------------------------------------------------------------
// Brand utilities — prevent mixing raw and sanitized values at compile time
// ---------------------------------------------------------------------------

declare const __brand: unique symbol;

/**
 * Branded type helper. A value of type Brand<T, B> is a T that has been
 * validated/sanitized and carries the phantom brand B.
 */
export type Brand<T, B extends string> = T & { readonly [__brand]: B };

/** A string confirmed to be free of XSS vectors. */
export type SafeHtml = Brand<string, 'SafeHtml'>;

/** A string confirmed to be safe for use in SQL LIKE patterns. */
export type SafeSqlLiteral = Brand<string, 'SafeSqlLiteral'>;

/** A string that has been fully decoded from all encoding layers. */
export type NormalizedString = Brand<string, 'NormalizedString'>;

// ---------------------------------------------------------------------------
// Parameterized query — the only safe way to interpolate user data into SQL
// ---------------------------------------------------------------------------

/**
 * Represents a SQL query that uses positional parameters ($1, $2, …) instead
 * of string interpolation. The `values` array maps 1-to-1 with parameter
 * placeholders. This type is the mandated output of the SQL sanitizer.
 */
export interface ParameterizedQuery {
  /** SQL template with $1…$N placeholders. Never contains raw user data. */
  readonly sql: string;
  /** Ordered parameter values. Each element maps to the corresponding $N. */
  readonly values: ReadonlyArray<string | number | boolean | null>;
}

// ---------------------------------------------------------------------------
// Result monad — typed success/failure without exceptions
// ---------------------------------------------------------------------------

export type Result<T, E> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly errors: E };

export function Ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

export function Err<E>(errors: E): Result<never, E> {
  return { ok: false, errors };
}

// ---------------------------------------------------------------------------
// Validation severity
// ---------------------------------------------------------------------------

export type ValidationSeverity = 'error' | 'warning';

// ---------------------------------------------------------------------------
// Field path — dot-notation path to the invalid field
// ---------------------------------------------------------------------------

export type FieldPath = string;

// ---------------------------------------------------------------------------
// Generic validated value wrapper
// ---------------------------------------------------------------------------

/**
 * Wraps a value together with metadata produced during validation.
 * Consumers should use `validated.value` for downstream processing.
 */
export interface Validated<T> {
  readonly value: T;
  /** Human-readable description of what transformations were applied. */
  readonly transformations: ReadonlyArray<string>;
}

// ---------------------------------------------------------------------------
// Validation rule contract
// ---------------------------------------------------------------------------

export interface ValidationRule<TInput, TOutput> {
  readonly name: string;
  readonly description: string;
  validate(input: TInput, field: FieldPath): Result<TOutput, import('../errors/validation-errors').ValidationError[]>;
}
