 * Centralized application error hierarchy.
 * Each error class carries an HTTP status code and a machine-readable code
 * so that the global error handler can serialise them without branching.
 */

export abstract class AppError extends Error {
  abstract readonly statusCode: number;
  abstract readonly errorCode: string;
  readonly isOperational: boolean = true;

  constructor(
    message: string,
    public readonly context?: Record<string, unknown>,
  ) {
    super(message);
    // Restore prototype chain broken by TypeScript class extension of Error
    Object.setPrototypeOf(this, new.target.prototype);
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ─── 400 Bad Request ────────────────────────────────────────────────────────

export class ValidationError extends AppError {
  readonly statusCode = 400;
  readonly errorCode = 'VALIDATION_ERROR';
}

// ─── 401 Unauthorized ───────────────────────────────────────────────────────

export class UnauthorizedError extends AppError {
  readonly statusCode = 401;
  readonly errorCode = 'UNAUTHORIZED';
}

// ─── 403 Forbidden ──────────────────────────────────────────────────────────

/**
 * Thrown when a valid user attempts to access a resource that belongs to a
 * different organization. We intentionally respond with 404 to avoid leaking
 * the existence of the resource to a cross-tenant attacker.
 */
export class ForbiddenResourceError extends AppError {
  readonly statusCode = 404; // Intentional: prevents IDOR enumeration
  readonly errorCode = 'RESOURCE_NOT_FOUND';

  constructor(
    resourceType: string,
    resourceId: string,
    organizationId: string,
  ) {
    super(`${resourceType} not found`, {
      resourceType,
      resourceId,
      organizationId,
    });
  }
}

// ─── 404 Not Found ──────────────────────────────────────────────────────────

export class NotFoundError extends AppError {
  readonly statusCode = 404;
  readonly errorCode = 'RESOURCE_NOT_FOUND';
}

// ─── 409 Conflict ───────────────────────────────────────────────────────────

export class ConflictError extends AppError {
  readonly statusCode = 409;
  readonly errorCode = 'CONFLICT';
}

// ─── 422 Unprocessable Entity ───────────────────────────────────────────────

export class UnprocessableError extends AppError {
  readonly statusCode = 422;
  readonly errorCode = 'UNPROCESSABLE';
}

// ─── 500 Internal Server Error ──────────────────────────────────────────────

export class InternalError extends AppError {
  readonly statusCode = 500;
  readonly errorCode = 'INTERNAL_ERROR';
  readonly isOperational = false;
}

// ─── Type guard ─────────────────────────────────────────────────────────────

export function isAppError(error: unknown): error is AppError {
  return error instanceof AppError;
}
