 * Domain types for API keys.
 *
 * Separation of concerns:
 *  - ApiKeyRow        : raw DB row (never leaves the repository layer)
 *  - ApiKeyRecord     : sanitised domain object (no hash, no raw key)
 *  - CreateApiKeyDTO  : input for key creation
 *  - ApiKeyCreatedResult : one-time response including the raw key
 *  - AuthenticatedKey : populated on successful middleware auth
 */

export type Permission = 'read' | 'write' | 'admin';

/**
 * Ordered permission levels — higher index = more powerful.
 * Used for hierarchical permission checks.
 */
export const PERMISSION_LEVELS: Record<Permission, number> = {
  read: 1,
  write: 2,
  admin: 3,
} as const;

/**
 * Returns true when `granted` satisfies the `required` permission level.
 * e.g. hasPermission(['write', 'read'], 'read') => true
 *      hasPermission(['read'], 'write')          => false
 */
export function hasPermission(
  granted: Permission[],
  required: Permission,
): boolean {
  const requiredLevel = PERMISSION_LEVELS[required];
  return granted.some(
    (p) => PERMISSION_LEVELS[p] >= requiredLevel,
  );
}

/**
 * Returns the highest-privilege permission in the list.
 */
export function maxPermission(permissions: Permission[]): Permission {
  if (permissions.length === 0) {
    throw new Error('permissions array must not be empty');
  }
  return permissions.reduce((max, p) =>
    PERMISSION_LEVELS[p] > PERMISSION_LEVELS[max] ? p : max,
  );
}

/**
 * Raw database row — contains the bcrypt hash.
 * Must NEVER be serialised to API responses.
 */
