      .join('\n');
    throw new Error(
      `Environment validation failed:\n${errors}\n\nPlease check your .env file.`,
    );
  }
  return result.data;
}

// Singleton – parsed once at startup
let _env: Env | null = null;

export function getEnv(): Env {
  if (_env === null) {
    _env = loadEnv();
  }
  return _env;
}

// Allows tests to inject a custom env object
export function setEnvForTesting(env: Env): void {
  _env = env;
}

export function resetEnv(): void {
