├─────────────────────────────────────────────────────┤
│  Service Layer                                       │
│  services/ApiKeyService.ts                          │
├─────────────────────────────────────────────────────┤
│  Repository Layer                                    │
│  repositories/ApiKeyRepository.ts                   │
