export interface BufferLine {
  /** Monotonically increasing sequence number */
  readonly seq: number;
  /** Raw content including ANSI escape codes */
  readonly raw: string;
  /** ANSI-stripped plain text for searching */
  readonly text: string;
  /** Timestamp when the line was received */
  readonly receivedAt: number;
}

/** Search match location */
export interface SearchMatch {
  /** Sequence number of the matching line */
  readonly lineSeq: number;
  /** Zero-based index of the line in the current buffer view */
  readonly lineIndex: number;
  /** Start character offset within the stripped text */
  readonly startOffset: number;
  /** End character offset within the stripped text */
  readonly endOffset: number;
}

/** Result returned by the search hook */
export interface SearchState {
  readonly query: string;
  readonly isRegex: boolean;
  readonly isCaseSensitive: boolean;
  readonly matches: readonly SearchMatch[];
  readonly activeMatchIndex: number;
  readonly isSearching: boolean;
