// Circular buffer with fixed capacity for terminal line storage
// Provides O(1) push and O(n) indexed access
// ---------------------------------------------------------------------------

import type { BufferLine } from '@/types/terminal';

const DEFAULT_CAPACITY = 50_000;

export class CircularBuffer {
  private readonly buffer: Array<BufferLine>;
  private readonly capacity: number;
  private head: number = 0;
  private size: number = 0;
  private totalPushed: number = 0;

  constructor(capacity: number = DEFAULT_CAPACITY) {
    if (capacity < 1) {
      throw new RangeError(`CircularBuffer capacity must be >= 1, got ${capacity}`);
    }
    this.capacity = capacity;
    this.buffer = new Array<BufferLine>(capacity);
  }

  /** Push a new line into the buffer. Returns the inserted BufferLine. */
  push(line: Omit<BufferLine, 'seq'>): BufferLine {
    const seq = this.totalPushed;
    const entry: BufferLine = { ...line, seq };
    this.buffer[(this.head + this.size) % this.capacity] = entry;
    if (this.size < this.capacity) {
      this.size++;
    } else {
      // Overwrite oldest — advance head
      this.head = (this.head + 1) % this.capacity;
    }
    this.totalPushed++;
    return entry;
  }

  /** Return all lines in insertion order (oldest → newest). */
  toArray(): ReadonlyArray<BufferLine> {
    const result: BufferLine[] = new Array<BufferLine>(this.size);
    for (let i = 0; i < this.size; i++) {
      const entry = this.buffer[(this.head + i) % this.capacity];
      if (entry !== undefined) {
        result[i] = entry;
      }
    }
    return result as ReadonlyArray<BufferLine>;
  }

  /** Return the line at logical index (0 = oldest). */
  at(index: number): BufferLine | undefined {
    if (index < 0 || index >= this.size) return undefined;
    return this.buffer[(this.head + index) % this.capacity];
  }

  /** Number of lines currently stored. */
  get length(): number {
    return this.size;
  }

  /** Total lines ever pushed (including overwritten). */
  get totalLines(): number {
    return this.totalPushed;
  }

  /** Remove all lines from the buffer. */
  clear(): void

