 * SQL Filter Domain Types
 *
 * Defines the complete type surface for dynamic query filter construction.
 * All types are strict-readonly to prevent mutation after validation.
 */

/** Allowed SQL comparison operators — exhaustive enum prevents injection via operator field */
export const SQL_OPERATORS = [
  '=',
  '!=',
  '<>',
  '<',
  '<=',
  '>',
  '>=',
  'LIKE',
  'NOT LIKE',
  'ILIKE',
  'NOT ILIKE',
  'IN',
  'NOT IN',
  'IS NULL',
  'IS NOT NULL',
  'BETWEEN',
] as const;

export type SqlOperator = (typeof SQL_OPERATORS)[number];

/** Scalar filter value — primitives only, no nested objects */
export type SqlFilterScalar = string | number | boolean | null;

/** Value accepted for IN/NOT IN operators */
export type SqlFilterArray = ReadonlyArray<SqlFilterScalar>;

/** Value accepted for BETWEEN operator — exactly two bounds */
export type SqlFilterBetween = readonly [SqlFilterScalar, SqlFilterScalar];

/** Union of all permissible raw filter values before validation */
export type SqlFilterRawValue = SqlFilterScalar | SqlFilterArray | SqlFilterBetween;

/** Logical combinator for compound filter groups */
export type SqlLogicalOperator = 'AND' | 'OR';

/**
 * A single atomic filter condition.
 * e.g. { field: 'email', operator: '=', value: 'user@example.com' }
 */
export interface SqlFilterCondition {
  readonly field: string;
  readonly operator: SqlOperator;
  readonly value: SqlFilterRawValue;
}

/**
 * A compound filter group combining multiple conditions.
 * Supports nested groups for complex AND/OR trees.
 */
export interface SqlFilterGroup {
  readonly logical: SqlLogicalOperator;
  readonly conditions: ReadonlyArray<SqlFilterCondition | SqlFilterGroup>;
}

/** Top-level filter input accepted by the pipeline */
export type SqlFilterInput = SqlFilterCondition | SqlFilterGroup;

/**
 * A validated, safe filter condition ready for parameterized query building.
 * Field has been allowlisted, operator validated, value sanitized.
 */
export interface ValidatedSqlFilter {
  readonly field: string;
  readonly operator: SqlOperator;
  readonly value: SqlFilterRawValue;
  readonly parameterPlaceholders: ReadonlyArray<string>;
  readonly parameterValues: ReadonlyArray<SqlFilterScalar>;
}

/**
 * A validated compound filter group.
 */
export interface ValidatedSqlFilterGroup {
  readonly logical: SqlLogicalOperator;
  readonly conditions: ReadonlyArray<ValidatedSqlFilter | ValidatedSqlFilterGroup>;
}

/** Union of validated filter output types */
export type ValidatedSqlFilterInput = ValidatedSqlFilter | ValidatedSqlFilterGroup;

/**
 * Configuration for which fields are permitted in filters.
 * Maps table alias -> allowed column names.
 */
export interface SqlFilterAllowlist {
  /** Set of fully-qualified or simple column names allowed in filter conditions */
  readonly allowedFields: ReadonlySet<string>;
  /** Maximum depth for nested filter groups (default: 5) */
  readonly maxDepth?: number;
  /** Maximum total conditions across entire filter tree (default: 20) */
  readonly maxConditions?: number;
}

/** Type guard: discriminates SqlFilterGroup from SqlFilterCondition */
export function isSqlFilterGroup(input: SqlFilterInput): input is SqlFilterGroup {
  return 'logical' in input && 'conditions' in input;
}

/** Type guard: discriminates ValidatedSqlFilterGroup from ValidatedSqlFilter */
export function isValidatedSqlFilterGroup(
  input: ValidatedSqlFilterInput,
): input is ValidatedSqlFilterGroup {
  return 'logical' in input && 'conditions' in input;
}
