/** Individual validation/sanitization error */
export interface ValidationError {
  /** Dot-separated path to the offending field (e.g. 'conditions[0].field') */
  readonly path: string;
  /** Machine-readable error code */
  readonly code: ValidationErrorCode;
  /** Human-readable message */
  readonly message: string;
  /** The raw value that caused the error (sanitized for logging — no PII guarantee) */
  readonly rawValue?: unknown;
}

/** Exhaustive error code enum */
export type ValidationErrorCode =
  | 'FIELD_NOT_ALLOWED'
  | 'INVALID_OPERATOR'
  | 'INVALID_VALUE_TYPE'
  | 'VALUE_TOO_LONG'
  | 'VALUE_TOO_SHORT'
  | 'INVALID_URL_PROTOCOL'
  | 'INVALID_URL_FORMAT'
  | 'INVALID_HANDLE_FORMAT'
  | 'NULL_BYTE_DETECTED'
  | 'MAX_DEPTH_EXCEEDED'
  | 'MAX_CONDITIONS_EXCEEDED'
  | 'BETWEEN_REQUIRES_TWO_VALUES'
  | 'IN_REQUIRES_ARRAY'
  | 'REQUIRED_FIELD_MISSING'
