│   │   ├── DiffEditorWrapper.tsx     # Monaco DiffEditor + decorations
│   │   ├── CommentOverlay.tsx        # Positions comment widgets
│   │   ├── CommentThread.tsx         # Individual thread UI
│   │   ├── CommentForm.tsx           # New comment / reply form
│   │   └── FileHeader.tsx            # File path, change stats
│   └── ui/
