// ─── Helpers ────────────────────────────────────────────────────────────────

function generateId(index: number, oldPath: string, newPath: string): string {
  const combined = `${index}:${oldPath}:${newPath}`;
  let hash = 0;
  for (let i = 0; i < combined.length; i++) {
    const chr = combined.charCodeAt(i);
    hash = (hash << 5) - hash + chr;
    hash |= 0;
  }
  return `file-${Math.abs(hash).toString(36)}`;
}

function parseHunkHeader(header: string): { oldStart: number; oldCount: number; newStart: number; newCount: number } {
  // Format: @@ -oldStart[,oldCount] +newStart[,newCount] @@
  const match = header.match(/@@ -([0-9]+)(?:,([0-9]+))? \+([0-9]+)(?:,([0-9]+))? @@/);
  if (!match) {
    return { oldStart: 1, oldCount: 0, newStart: 1, newCount: 0 };
  }
  return {
    oldStart: parseInt(match[1], 10),
    oldCount: match[2] !== undefined ? parseInt(match[2], 10) : 1,
    newStart: parseInt(match[3], 10),
    newCount: match[4] !== undefined ? parseInt(match[4], 10) : 1,
  };
}

function determineDiffFileStatus(oldPath: string, newPath: string, hunks: readonly DiffHunk[], isBinary: boolean): DiffFileStatus {
  if (isBinary) return 'binary';
  const isNullOld = oldPath === '/dev/null';
  const isNullNew = newPath === '/dev/null';
  if (isNullOld) return 'added';
  if (isNullNew) return 'deleted';
  if (oldPath !== newPath) return 'renamed';
  if (hunks.length === 0) return 'unknown';
  return 'modified';
}

function reconstructContents(hunks: readonly DiffHunk[]): { original: string; modified: string } {
  if (hunks.length === 0) return { original: '', modified: '' };

  const originalLines: string[] = [];
  const modifiedLines: string[] = [];

  let expectedOldLine = 1;
  let expectedNewLine = 1;

  for (const hunk of hunks) {
    // Fill gap before hunk with placeholder context indicator
    while (expectedOldLine < hunk.oldStart) {
      const gap = `// ... (line ${expectedOldLine})`;
      originalLines.push(gap);
      expectedOldLine++;
    }
    while (expectedNewLine < hunk.newStart) {
      const gap = `// ... (line ${expectedNewLine})`;
      modifiedLines.push(gap);
      expectedNewLine++;
    }

    for (const line of hunk.lines) {
