import { ValidationViolation } from './types';

/** Base class for all pipeline errors */
export class PipelineError extends Error {
  public readonly code: string;
  public readonly context: Record<string, unknown>;

  constructor(
    message: string,
    code: string,
    context: Record<string, unknown> = {},
  ) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.context = context;
    // Maintains proper prototype chain in transpiled ES5
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/** Thrown when input fails structural or domain validation */
export class ValidationError extends PipelineError {
  public readonly violations: ReadonlyArray<ValidationViolation>;

  constructor(
    violations: ReadonlyArray<ValidationViolation>,
    context: Record<string, unknown> = {},
  ) {
    const summary = violations
      .map((v) => `[${v.field}] ${v.message}`)
      .join('; ');
    super(`Validation failed: ${summary}`, 'VALIDATION_FAILED', context);
    this.violations = violations;
  }
}

/** Thrown when a filter expression references an unknown schema field */
