 * Atomic, composable validation rule functions.
 * Each rule is a pure function: (value, field) => ValidationViolation[]
 * An empty array means the value passed the rule.
 */

import { ValidationRule, ValidationViolation } from './types';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function violation(
  field: string,
  code: string,
  message: string,
  receivedValue?: unknown,
): ValidationViolation {
  return { field, code, message, severity: 'error', receivedValue };
}

// ---------------------------------------------------------------------------
// Primitive type rules
// ---------------------------------------------------------------------------

/** Ensures a value is a non-null, non-undefined string */
export const isString: ValidationRule<unknown> = (
  value,
  field,
): ValidationViolation[] => {
  if (typeof value !== 'string') {
    return [
      violation(
        field,
        'TYPE_STRING',
        `Expected a string but received ${typeof value}`,
        value,
      ),
    ];
  }
  return [];
};

/** Ensures a value is a finite number */
export const isNumber: ValidationRule<unknown> = (
  value,
  field,
): ValidationViolation[] => {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return [
      violation(
