 * Typed error hierarchy for the application.
 *
 * Security note: All not-found and forbidden errors for tenant-scoped resources
 * are surfaced as 404 to avoid confirming existence of cross-tenant objects
 * (prevents enumeration attacks).
 */

export type ErrorCode =
  | 'VALIDATION_ERROR'
  | 'AUTHENTICATION_REQUIRED'
  | 'INVALID_TOKEN'
  | 'INSUFFICIENT_PERMISSIONS'
  | 'RESOURCE_NOT_FOUND'
  | 'TENANT_MISMATCH'          // IDOR guard triggered
  | 'CONFLICT'
  | 'INTERNAL_ERROR';

export class AppError extends Error {
  public readonly statusCode: number;
  public readonly errorCode: ErrorCode;
  public readonly isOperational: boolean;

  constructor(
    message: string,
    statusCode: number,
    errorCode: ErrorCode,
    isOperational = true,
  ) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.isOperational = isOperational;
  }
}

export class ValidationError extends AppError {
  public readonly fieldErrors: Record<string, string>;

  constructor(message: string, fieldErrors: Record<string, string> = {}) {
    super(message, 400, 'VALIDATION_ERROR');
    this.fieldErrors = fieldErrors;
  }
}

export class AuthenticationError extends AppError {
  constructor(message = 'Authentication required') {
    super(message, 401, 'AUTHENTICATION_REQUIRED');
  }
}

export class InvalidTokenError extends AppError {
  constructor(message = 'Invalid or expired token') {
    super(message, 401, 'INVALID_TOKEN');
  }
}

export class InsufficientPermissionsError extends AppError {
  constructor(message = 'Insufficient permissions') {
    super(message, 403, 'INSUFFICIENT_PERMISSIONS');
  }
}

/**
 * Used for both genuine not-found AND cross-tenant IDOR attempts.
 * Returning 404 for IDOR prevents attackers from learning a resource exists
 * in another tenant by observing 403 vs 404 response codes.
 */
export class ResourceNotFoundError extends AppError {
  constructor(resourceType: string, resourceId: string) {
    super(
      `${resourceType} with id '${resourceId}' not found`,
      404,
      'RESOURCE_NOT_FOUND',
    );
  }
}

/**
 * Internal marker error — converted to ResourceNotFoundError before
 * being sent to the client so tenants cannot distinguish "not found"
 * from "belongs to another tenant".
 */
export class TenantMismatchError extends AppError {
  public readonly resourceType: string;
  public readonly resourceId: string;
  public readonly requestingOrgId: string;
  public readonly owningOrgId: string;

  constructor(
    resourceType: string,
    resourceId: string,
    requestingOrgId: string,
    owningOrgId: string,
  ) {
    // Intentionally vague message — real detail goes to audit log only
    super(
      `${resourceType} with id '${resourceId}' not found`,
      404,
      'TENANT_MISMATCH',
    );
    this.resourceType = resourceType;
    this.resourceId = resourceId;
    this.requestingOrgId = requestingOrgId;
    this.owningOrgId = owningOrgId;
  }
}

export class ConflictError extends AppError {
  constructor(message: string) {
    super(message, 409, 'CONFLICT');
  }
}

export class InternalError extends AppError {
  constructor(message = 'Internal server error') {
    super(message, 500, 'INTERNAL_ERROR', false);
  }
}
